export type AccountType = 'ASSET' | 'LIABILITY' | 'EQUITY' | 'INCOME' | 'EXPENSE';

export interface Account {
  id: string;
  name: string;
  type: AccountType;
  currency: string;
  institution?: string;
  investmentType?: 'BROKERAGE' | 'RETIREMENT' | null;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export type PostingDirection = 'DEBIT' | 'CREDIT';

export interface Posting {
  id: string;
  transactionId: string;
  accountId: string;
  amount: number;
  currency: string;
  direction: PostingDirection;
  categoryId?: string;
  fundId?: string;
  assetSymbol?: string;
  quantity?: number;
  unitPrice?: number;
  feeAmount?: number;
}

export type TransactionStatus = 'CONFIRMED' | 'VOIDED';
export type TransactionSource = 'MANUAL' | 'IMPORT' | 'ASSISTANT' | 'RULE';

export interface Transaction {
  id: string;
  date: string;
  description: string;
  status: TransactionStatus;
  source: TransactionSource;
  idempotencyKey: string;
  revision: number;
  voidedAt?: string;
  voidReason?: string;
  postings: Posting[];
  createdAt: string;
  updatedAt: string;
}

export type CategoryType = 'INCOME' | 'EXPENSE';

export interface Category {
  id: string;
  name: string;
  parentId?: string;
  type: CategoryType;
}

export interface Fund {
  id: string;
  name: string;
  targetAmount: number;
  currency: string;
  priority: number;
  createdAt: string;
  updatedAt: string;
}

export interface BalanceSnapshot {
  id: string;
  accountId: string;
  date: string;
  amount: number;
  currency: string;
  source: TransactionSource;
  createdAt: string;
}

export interface ExchangeRate {
  id: string;
  fromCurrency: string;
  toCurrency: string;
  rate: number;
  date: string;
  source: string;
}

export type AuditAction = 'CREATE' | 'UPDATE' | 'VOID';

export interface AuditLogEntry {
  id: string;
  entityType: string;
  entityId: string;
  action: AuditAction;
  before?: unknown;
  after?: unknown;
  source: TransactionSource;
  createdAt: string;
}

export interface CreateTransactionPayload {
  date: string;
  description: string;
  source: TransactionSource;
  idempotencyKey: string;
  postings: Omit<Posting, 'id' | 'transactionId'>[];
}

export interface CreateAccountPayload {
  name: string;
  type: AccountType;
  currency: string;
  institution?: string;
  investmentType?: 'BROKERAGE' | 'RETIREMENT' | null;
}

export interface UpdateAccountPayload {
  id: string;
  name?: string;
  isActive?: boolean;
}

export interface CreateFundPayload {
  name: string;
  targetAmount: number;
  currency: string;
  priority?: number;
}

export interface CreateBalanceSnapshotPayload {
  accountId: string;
  date: string;
  amount: number;
  currency: string;
  source: TransactionSource;
}

export type Command =
  | { type: 'CREATE_TRANSACTION'; payload: CreateTransactionPayload }
  | { type: 'VOID_TRANSACTION'; payload: { id: string; reason: string } }
  | { type: 'CREATE_ACCOUNT'; payload: CreateAccountPayload }
  | { type: 'CREATE_ACCOUNTS'; payload: { accounts: CreateAccountPayload[] } }
  | { type: 'UPDATE_ACCOUNT'; payload: UpdateAccountPayload }
  | { type: 'CREATE_FUND'; payload: CreateFundPayload }
  | { type: 'RECORD_BALANCE_SNAPSHOT'; payload: CreateBalanceSnapshotPayload };

export interface TransactionProposal {
  type: 'EXPENSE' | 'INCOME' | 'TRANSFER' | 'FUND_CREATE';
  amount: number;
  currency: string;
  date: string;
  description: string;
  categoryId?: string;
  accountHint?: string;
  categoryHint?: string;
  sourceAccountHint?: string;
  destinationAccountHint?: string;
  /** EXPENSE/INCOME: existing fund hint; FUND_CREATE: the new fund's name. */
  fundHint?: string;
  sourceAccountId?: string;
  destinationAccountId?: string;
  fundId?: string;
  breakdown?: BreakdownItem[];
  note?: string;
  needsConfirmation: true;
}

export interface BreakdownItem {
  label: string;
  amount: number;
  kind: 'ITEM' | 'TRANSFER' | 'EXPENSE' | 'SAVINGS' | 'INVESTMENT';
  toSource?: string;
  categoryId?: string;
}

export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };
